'use strict';
const campusFacilities=[
{id:'sprint',name:'100 METRE TESİSİ',label:'100 METRE',icon:'shoe',x:25,y:25,area:[6,11,36,14],rows:[['Çıkış Hızı','İlk 25 m',1,2,'shoe'],['Sprint Gücü','Genel hız',1,3,'speed'],['Finiş Gücü','Son 20 m',1,3,'finish']]},
{id:'hurdles',name:'ENGELLİ KOŞU TESİSİ',label:'ENGELLİ KOŞU',icon:'speed',x:79,y:26,area:[63,11,29,12],rows:[['Engel Ritmi','Engeller arası hız',1,2,'speed'],['Atlayış Tekniği','Engel kaybı',1,3,'shoe'],['Finiş Temposu','Son bölüm hız',1,3,'finish']]},
{id:'swim',name:'YÜZME TESİSİ',label:'YÜZME',icon:'stamina',x:16,y:47,area:[2,29,27,16],rows:[['Çıkış Tepkisi','İlk 25 m',1,2,'shoe'],['Kulaç Gücü','Genel hız',1,3,'speed'],['Nefes Kontrolü','Son 25 m',1,3,'stamina']]},
{id:'stadium',name:'STADYUM',label:'STADYUM',icon:'stadium',x:56,y:50,area:[34,28,40,21],rows:[['Tribün Kapasitesi','Tribün geliri',5,2,'team'],['Bilet Geliri','Bilet kazancı',5,3,'ticket'],['Sponsorluk','Yarış ödülü',3,3,'trophy']]},
{id:'jump',name:'UZUN ATLAMA TESİSİ',label:'UZUN ATLAMA',icon:'shoe',x:20,y:66,area:[4,54,30,12],rows:[['Koşu Hızı','Yaklaşma',1,2,'shoe'],['Sıçrama Gücü','Atlayış',1,3,'speed'],['İniş Tekniği','Mesafe',1,3,'finish']]},
{id:'weights',name:'HALTER TESİSİ',label:'HALTER',icon:'stamina',x:53,y:70,area:[39,55,25,14],rows:[['Temel Güç','Kaldırış',1,2,'stamina'],['Denge','Başarı şansı',1,3,'medal'],['Son Hamle','Final güç',1,3,'finish']]},
{id:'archery',name:'OKÇULUK TESİSİ',label:'OKÇULUK',icon:'medal',x:86,y:66,area:[76,52,18,14],rows:[['Nişan Tekniği','İsabet',1,2,'medal'],['Yay Gücü','Atış puanı',1,3,'stamina'],['Odaklanma','Son atış',1,3,'finish']]}
];
const campusPage=document.createElement('section');campusPage.id='campus-page';campusPage.hidden=true;campusPage.setAttribute('aria-label','Kampüs');document.body.append(campusPage);
let campusSelection='sprint',campusReturnFocus=null;
function campusCost(id,i){const f=campusFacilities.find(f=>f.id===id);return f.rows[i][3]+campusRank(id,i);}
function buyCampusUpgrade(id,i){const f=campusFacilities.find(f=>f.id===id);if(!f||f.locked||!Number.isInteger(i)||i<0||i>=3||campusRank(id,i)>=5)return false;const cost=campusCost(id,i);if(state.skillPoints<cost)return false;state.skillPoints-=cost;state.campusUpgrades[id]??=[0,0,0];state.campusUpgrades[id][i]++;save();update();return true;}
function campusLabels(){return campusFacilities.map(f=>{const [x,y,w,h]=f.area;const level=1+[0,1,2].reduce((n,i)=>n+campusRank(f.id,i),0);return `<button class="campus-hit" data-facility="${f.id}" aria-label="${f.name}${f.locked?' — yakında':''}" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%"></button><button class="campus-marker" data-facility="${f.id}" style="left:${f.x}%;top:${f.y}%"><strong>${f.label}</strong><span>${f.locked?'🔒 YAKINDA':'Sv. '+level+'　⬆'}</span></button>`}).join('');}
function openCampus(){campusReturnFocus=document.activeElement;$('#modal').close();campusPage.hidden=false;$('.game').inert=true;document.body.classList.add('campus-open');campusPage.innerHTML=`<div class="campus-scroll"><div class="campus-world"><img class="campus-map" src="assets/campus-map.png" alt="Ortada stadyum, çevresinde altı yarış tesisi bulunan kampüs"><header class="campus-top"><button id="campus-back" aria-label="Oyuna dön">←</button><h1>KAMPÜS</h1><button id="campus-sp" aria-label="Skill puanı hakkında">★ <b>${state.skillPoints}</b> SP</button></header><div id="campus-markers">${campusLabels()}</div><p class="campus-tip">Bir tesise dokun · Her 5 yarışta +1 SP</p></div></div><dialog id="campus-upgrade" aria-labelledby="campus-upgrade-title"></dialog>`;$('#campus-back').focus();$('#campus-upgrade').addEventListener('click',e=>{if(e.target===$('#campus-upgrade'))$('#campus-upgrade').close();});}
function closeCampus(){campusPage.hidden=true;$('.game').inert=false;document.body.classList.remove('campus-open');$('#campus-upgrade')?.close();selectNav($('.bottom [data-open="race"]'));campusReturnFocus?.focus();}
function showCampusFacility(id){const f=campusFacilities.find(f=>f.id===id);if(!f)return;campusSelection=id;const d=$('#campus-upgrade');const rank=1+[0,1,2].reduce((n,i)=>n+campusRank(id,i),0);d.innerHTML=`<button class="campus-modal-close" id="campus-modal-close" aria-label="Yükseltmeleri kapat">×</button><header class="campus-modal-head"><span class="campus-icon-box"><span class="art" data-art="${f.icon}"></span></span><div><h2 id="campus-upgrade-title">${f.name}</h2><p>Kalıcı geliştirmeler</p><b class="campus-level">${f.locked?'YAKINDA':'Sv. '+rank}</b></div></header>${f.locked?'<p class="campus-locked-note">Bu yarış dalı açıldığında geliştirmeler kullanılabilir.</p>':''}<div class="campus-upgrades">${f.rows.map(([name,effect,amount,base,icon],i)=>{const n=campusRank(id,i),cost=campusCost(id,i);return `<div class="campus-upgrade-row"><span class="campus-small-icon"><span class="art" data-art="${icon}"></span></span><div class="campus-upgrade-copy"><h3>${name}</h3><p>${effect} <em>${amount<0?'−':'+'}%${Math.abs(amount)*(n+1)}</em></p><small>${n}/5 · Mevcut: ${amount<0?'−':'+'}%${Math.abs(amount)*n}</small></div><span class="campus-price">★ ${n>=5?'MAKS.':cost+' SP'}</span><button data-campus-buy="${i}" aria-label="${name} geliştir, ${cost} SP" ${f.locked||n>=5||state.skillPoints<cost?'disabled':''}>${f.locked?'🔒':n>=5?'✓':'↑'}</button></div>`}).join('')}</div><p class="campus-modal-note">${f.locked?'Skill puanın harcanmaz.':race&&id==='sprint'?'Yeni bonuslar sonraki yarışta uygulanır.':'Kalıcı bonuslar otomatik uygulanır.'}</p>`;arts(d);if(!d.open)d.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.facility)showCampusFacility(b.dataset.facility);if(b.dataset.campusBuy!==undefined){const i=Number(b.dataset.campusBuy);if(buyCampusUpgrade(campusSelection,i)){beep(880);$('#campus-sp b').textContent=state.skillPoints;$('#campus-markers').innerHTML=campusLabels();showCampusFacility(campusSelection);toast('Kalıcı geliştirme alındı!');}}if(b.id==='campus-back')closeCampus();if(b.id==='campus-modal-close')$('#campus-upgrade').close();if(b.id==='campus-sp')toast('Başlangıçta 8 SP; tamamlanan her 5 yarışta +1 SP.');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!campusPage.hidden&&!$('#campus-upgrade').open){closeCampus();}});
let lastCampusPoints=-1;
setInterval(()=>{if(!campusPage.hidden&&state.skillPoints!==lastCampusPoints){lastCampusPoints=state.skillPoints;$('#campus-sp b').textContent=state.skillPoints;if($('#campus-upgrade').open)showCampusFacility(campusSelection);}},1000);
